def rot13(text):
    result = ""
    for char in text:
        if char.isalpha():
            ascii_offset = 97 if char.islower() else 65
            result += chr((ord(char) - ascii_offset + 13) % 26 + ascii_offset)
        else:
            result += char
    return result

inputs = ["apple", "bridge", "candle", "dragon", "engine", "forest", "guitar", "hollow", "island", "jacket", "kitten", "ladder", "meadow", "needle", "orange", "pillow", "quiver", "rocket", "summer", "turtle"]
outputs = [rot13(word) for word in inputs]
for i, output in enumerate(outputs, start=1):
    print(f"{i}. {output}")

